merged_files.inquiry/search.py:
"""顧客番号で問い合わせを探す。"""


def by_customer(inquiries, customer_id):
    """その顧客の問い合わせを新しい順に返す。"""
    rows = [i for i in inquiries if i["customer_id"] == customer_id]
    return sorted(rows, key=lambda i: i["received_at"], reverse=True)

merged_files.inquiry/detail.py:
"""問い合わせの詳細を開く。"""


def open_detail(inquiries, inquiry_id):
    return next(i for i in inquiries if i["id"] == inquiry_id)
